from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1];B=json.loads((ROOT/'study/diagnostic-data.json').read_text())
# Authored practice: facts exist only within these fictional passages, not as external factual claims.
rows=[
('POS','전시 안내문','The exhibition presents an impress___ collection of handmade maps. Every map was produced by a local artist.','Choose the form that correctly completes impress___.',['impression','impressive','impressively','impresses'],'B','collection을 수식하는 형용사 impressive가 필요하다. 명사나 부사·서술 동사는 이 자리에 맞지 않는다.'),
('POS','학생 지원 프로그램','The program supports students by providing equipment and offer___ weekly feedback. Both services are free.','Choose the form that correctly completes offer___.',['offered','offers','offering','offer'],'C','by 뒤에서 providing과 병렬을 이루는 동명사 offering이 필요하다.'),
('ENTITY','대상·특징 · 팀','In a project team, the coordinator assigns tasks, the researcher gathers evidence, and the editor checks the final wording. Each person has a separate responsibility.','Who is responsible for checking the wording?',['The researcher','The coordinator','All team members equally','The editor'],'D','checks the final wording의 주체는 editor다. 다른 사람의 역할을 옮겨 붙이면 안 된다.'),
('ENTITY','대상·특징 · 장치','Device Orion records changes in light. Device Vega measures temperature. Device Lyra sends an alert when moisture falls below a set level.','Which device monitors temperature?',['Vega','Lyra','Orion','Both Orion and Lyra'],'A','온도 측정은 Vega의 특징이다. 광량과 수분 관련 특징은 다른 장치의 것이다.'),
('SCOPE','질문의 범위 · 식량','The new storage containers reduce grain loss after harvest. They also use less plastic than the old containers. The report discusses both food supply and material use.','How do the containers help the food supply?',['They reduce the amount of plastic used.','They prevent some harvested grain from being lost.','They make every crop grow faster.','They replace all farming equipment.'],'B','food supply를 묻기 때문에 grain loss 감소가 근거다. 플라스틱 감소는 참이지만 다른 범위의 정보다.'),
('SCOPE','질문의 범위 · 사례 역할','The author describes a busy station and a crowded market. In both places, clear signs help visitors find their way. The examples illustrate the value of simple directions.','Why does the author mention the two places?',['To show that markets are busier than stations','To argue that all signs should be removed','To illustrate how signs assist navigation','To explain why visitors avoid public transport'],'C','두 사례의 공통 역할은 길 찾기를 돕는 표지판의 가치다. 한 장소만의 추가 특징으로 좁히지 않는다.'),
('FUNCTION','발화 기능 · 요청','A: Could you send me the draft before lunch?\nB: ______','Which response best answers the request?',['I appreciate your offer.','You enjoyed lunch yesterday.','The draft was very interesting.','Sure. I will email it this morning.'],'D','A는 초안 전송을 요청했다. 수락하고 전송 행동을 약속하는 응답이 맞다.'),
('FUNCTION','발화 기능 · 간접 거절','A: Can you join our planning group this week?\nB: I am already stretched with two deadlines.','What does B most likely mean?',['B probably cannot take on the extra work.','B wants to extend both deadlines.','B has already joined the group.','B is asking where the meeting will be.'],'A','추가 업무 요청에 현재 여력이 없다고 답하므로 참여가 어렵다는 간접 거절이다.'),
('DIRECT','직접 정보 · 다음 행동','A: We need a room for the workshop.\nB: I will call the community center after lunch. You can prepare the invitation.\nA: All right.','What will B do next?',['Write the invitation','Contact the community center','Attend the workshop immediately','Cancel the workshop'],'B','B가 직접 말한 다음 행동은 community center에 전화하는 것이다. A의 역할과 구분한다.'),
('DIRECT','직접 정보 · 장소','The notice says: Our volunteer orientation will take place in the Cedar Room on the second floor. Registration is at the front desk on the first floor.','Where will the orientation take place?',['At the front desk','On the first-floor terrace','In the Cedar Room','In the registration office'],'C','orientation 장소는 Cedar Room이고, front desk는 등록 장소다.'),
('MEANING','교통 소음 안내','The barriers mitigate the effect of traffic noise, although residents can still hear passing buses.','What does mitigate mean here?',['Identify','Completely remove','Make worse','Reduce'],'D','소음이 여전히 들리므로 완전 제거가 아닌 영향 감소·완화다.'),
('MEANING','실험 관찰 기록','After the liquid evaporated, a thin residue remained at the bottom of the dish.','What does residue refer to?',['Material left after the process','A person who lives nearby','The liquid before heating','An instruction for cleaning'],'A','과정 뒤 남은 물질이라는 문맥이다. 형태가 비슷한 resident와 구분한다.'),
('CHANGE','변경 전후 · 공지','The workshop was originally scheduled for Room 12. Because that room is being repaired, it will now be held in Room 18. The start time is unchanged.','Where should participants go?',['Room 12','Room 18','The repair office','Either room, depending on arrival time'],'B','원래 장소와 현재 장소를 구분한다. now와변경 사유 이후의 Room 18이 현재 적용 장소다.'),
('CHANGE','조건 · 신청','Applications received by Friday will be considered for the first round. Later applications will be reviewed only if places remain.','Which statement is supported?',['Every late applicant is guaranteed a place.','The first round begins before any application arrives.','Late applications depend on remaining places.','Friday applications are never considered.'],'C','늦은 신청은 잔여 자리라는 조건이 있다. 조건을 제거한 일반화는 근거가 없다.'),
('EVIDENCE','근거 없는 평가 제외','The team tested the filter in three ponds and reported lower sediment levels in each. The passage gives no information about public opinion.','Which statement is supported?',['The filter was unpopular with residents.','The team tested every pond in the country.','The filter removed all sediment permanently.','The tested ponds showed lower sediment levels.'],'D','세 연못의 침전물 수치 감소만 직접 근거가 있다. 인기·전국 확대·완전 제거를 덧붙일 수 없다.'),
('EVIDENCE','부분 일치 · 추가 주장','The archive offers free access to scanned letters. Printed copies can be ordered for a small fee.','Which statement accurately describes the service?',['Digital access is free, but printed copies cost money.','All services, including printed copies, are free.','Printed copies are unavailable.','Only researchers may view the letters.'],'A','무료인 부분과 유료인 부분을 모두 확인한다. 일부만 맞는 무료 서비스 주장으로 전체를 일반화하면 안 된다.'),
('CAUSE','원인·결과 · 수분','In the experiment, reducing soil moisture slowed seedling growth. The researchers changed moisture first and measured growth afterward.','Which relationship is described?',['Slower growth caused the soil to become drier.','Lower soil moisture led to slower growth.','Faster growth increased soil moisture.','Moisture and growth were never compared.'],'B','변경한 원인은 수분 감소, 측정된 결과는 성장 둔화다.'),
('CAUSE','원인·결과 · 일정','A delivery delay left the studio without paper, so the printing session was postponed. The delivery delay happened before the postponement.','Why was the session postponed?',['The studio had printed too many copies.','The session itself delayed the delivery.','The studio did not receive the paper in time.','The studio decided never to print again.'],'C','제때 종이를 받지 못한 것이 원인이고 인쇄 일정 연기는 결과다.'),
('TIME','시간축 · 완료 여부','A: Have you submitted the form yet?\nB: Not yet, but I will upload it after the meeting.','Which statement is correct?',['The form was uploaded before the meeting.','The meeting has been canceled.','B refuses to submit the form.','B has not submitted it and plans to do so later.'],'D','Not yet는 미완료이고 will은 미래 계획이다. 이미 제출했다는 뜻으로 읽지 않는다.'),
('TIME','시간축 · 마감','The early registration period ended yesterday. The event itself will take place next month, and regular registration is still open.','What has already ended?',['Early registration','The event','All registration','The next month'],'A','끝난 것은 조기 등록 기간이다. 행사 날짜와 일반 등록 상태를 분리한다.'),
('INSERT','연결 기능 · 요약','Mina checks every file name. She then compares each file with the index and corrects missing labels.','Which sentence best summarizes the process?',['However, Mina has never used an index.','In short, Mina verifies that the files are labeled consistently.','For example, the room contains three chairs.','Before this, the files had not been created.'],'B','앞의 여러 확인 행동을 요약하는 In short 문장이 맞다. 새로운 무관한 예시나 반대 주장은 연결되지 않는다.'),
('INSERT','연결 기능 · 지시어','Rainwater enters the garden through a shallow channel. It then passes slowly through layers of gravel and soil.','What does This process refer to in the next sentence, This process removes some particles?',['Building the garden fence','Adding more gravel next year','Water moving through the channel and layers','Particles falling directly into a bin'],'C','This process는 앞의 물 이동·여과 과정을 받는다. 본문에 없는 새 과정을 가리키지 않는다.'),
('MAIN','전체 주제 · 강의','A talk first explains why libraries preserve recordings. It then describes storage conditions, digital backups, and ways to help visitors find the files.','Which title best covers the whole talk?',['Why visitors dislike digital files','The invention of a single recording machine','A comparison of two library buildings','How libraries preserve and provide access to recordings'],'D','보존 이유·보관 방법·백업·접근을 모두 아우르는 제목이다. 한 세부 내용만 골라서는 안 된다.'),
('INFER','필요한 추론 · 역할','The email tells customers: You may order the notebooks in boxes of fifty and receive a discount when buying several boxes for your shop.','Who is the email most likely intended for?',['Retailers purchasing stock','Visitors borrowing a notebook','Writers submitting a manuscript','Staff repairing the warehouse'],'A','상점용으로 여러 상자를 구매한다는 단서가 소매업자를 뒷받침한다. 그 이상의 배경은 필요하지 않다.')]
rows += [
('SPELL','철자 확인 · 명사','The instructions were completely clear, so there was no confu____ about the meeting place.','Which spelling correctly completes the sentence?',['confusion','confussion','confuson','confusian'],'A','제시 철자 confu 뒤에 sion을 붙인 confusion이 올바른 철자다. 문장에는 혼란을 뜻하는 명사가 필요하다.'),
('SPELL','철자 확인 · 단어 형태','The guide described the route with great accu____, including the distance between each stop.','Which spelling correctly completes the sentence?',['accurancy','accuracy','accurracy','accurasy'],'B','정확성을 뜻하는 명사는 accuracy다. 제시 철자 accu 뒤에 racy를 붙이고 완성한 단어를 대조한다.'),
('COLLOC','결합 표현 · 시간','The earliest records of this local festival date ____ to the early eighteenth century.','Which word completes the expression?',['after','beyond','back','away'],'C','date back to는 기원이 과거의 특정 시점까지 거슬러 올라간다는 결합 표현이다.'),
('COLLOC','결합 표현 · 동사 구조','The new schedule allows students ____ attend both sessions without missing lunch.','Which word completes the sentence?',['for','at','of','to'],'D','allow + 목적어 + to부정사 구조다. students가 attend하는 주체이며 allows students to attend가 된다.')]

transfers=[]
for n,(key,title,passage,prompt,choices,answer,explanation) in enumerate(rows,1):
 rule=next(r for r in B['rules'] if r['id']=='RULE-'+key)
 ids=[qid for qid,s in B['suggestions'].items() if s['ruleId']==rule['id']]
 transfers.append(dict(id=f'TRANSFER-{n:02}',title=title,passage=passage,prompt=prompt,options=dict(zip('ABCD',choices)),answer=answer,explanation=explanation,ruleId=rule['id'],targetCode=rule['code'],source_error_ids=ids,kind='authored_transfer',section='Reading',ready=True,provenance='직접 만든 신규 연습. 공식 TPO 문항이 아니며 발화 문제도 텍스트 이해 훈련으로 집계.'))
(ROOT/'study/transfer-data.json').write_text(json.dumps(transfers,ensure_ascii=False,indent=2));(ROOT/'study/transfer-data.js').write_text('window.TOEFL_TRANSFER='+json.dumps(transfers,ensure_ascii=False)+';\n');print(len(transfers),'authored transfer questions')
